     2→import { codeQualityAnalyzer, testCoverageAnalyzer, refactoringSuggester } from './agents/index.js';
     3→import { orchestratorPrompt } from './prompts/index.js';
     4→import { ReviewReport, ReviewReportSchema } from './types/index.js';
     5→import { Logger } from './utils/logger.js';
     6→
     7→export class Orchestrator {
     8→  private client: Anthropic;
     9→
    10→  constructor() {
    11→    this.client = new Anthropic({
    12→      apiKey: process.env.ANTHROPIC_API_KEY,
    13→    });
    14→  }
    15→
    16→  async reviewPullRequest(owner: string, repo: string, prNumber: number): Promise<ReviewReport> {
    17→    Logger.info('Starting code review', { owner, repo, prNumber });
    18→
    19→    // Build the user message with PR information
    20→    const userMessage = `Please review the following GitHub pull request and provide a comprehensive code review analysis:
    21→
    22→Repository: ${owner}/${repo}
    23→Pull Request Number: #${prNumber}
    24→
    25→Analyze this PR by conducting three specialized analyses:
    26→
    27→1. **Code Quality Analysis**: Identify security vulnerabilities, performance issues, and maintainability concerns
    28→2. **Test Coverage Analysis**: Evaluate test completeness and suggest specific test cases
    29→3. **Refactoring Opportunities**: Identify structural improvements and modernization opportunities
    30→
    31→IMPORTANT: Respond with ONLY a valid JSON object (no markdown, no code blocks, no explanations).
    32→
    33→The JSON MUST have this exact structure with ALL required fields:
    34→{
    35→  "owner": "${owner}",
    36→  "repo": "${repo}",
    37→  "prNumber": ${prNumber},
    38→  "codeQuality": {
    39→    "agent": "code-quality-analyzer",
    40→    "summary": "Summary of code quality assessment",
    41→    "issues": [
    42→      {
    43→        "id": "code-001",
    44→        "title": "Security Issue",
    45→        "description": "Detailed description of the issue",
    46→        "severity": "high",
    47→        "file": "src/example.ts",
    48→        "line": 42,
    49→        "suggestion": "Recommended fix or improvement"
    50→      }
    51→    ],
